/**
 * Strips invisible Unicode from untrusted model text (OWASP LLM Top 10 2026,
 * LLM01; #4711). These characters are invisible yet readable by a model, so
 * they can carry hidden instructions or smuggled text.
 *
 * The set is the generated `INVISIBLE_RANGES` table
 * (`$lib/invisible-table`): every Default_Ignorable_Code_Point plus
 * U+FFF9..U+FFFB. It is generated by scripts/gen-invisible.mjs, which also
 * generates the Rust copy the backend uses, and CI fails if either is stale.
 *
 * No exceptions: variation selectors (including U+FE0E / U+FE0F) are stripped
 * too. A "keep a selector after a visible character" rule leaks hidden bits
 * across markup boundaries (`**{selector}**` repeated survives).
 */
import { INVISIBLE_RANGES } from '$lib/invisible-table';

/** Binary search over the sorted, non-overlapping ranges. */
export function isInvisible(cp: number): boolean {
	let lo = 0;
	let hi = INVISIBLE_RANGES.length - 1;
	while (lo <= hi) {
		const mid = (lo + hi) >> 1;
		const [from, to] = INVISIBLE_RANGES[mid];
		if (cp < from) hi = mid - 1;
		else if (cp > to) lo = mid + 1;
		else return true;
	}
	return false;
}

export function stripInvisible(text: string): string {
	let out = '';
	for (const ch of text) {
		if (!isInvisible(ch.codePointAt(0)!)) out += ch;
	}
	return out;
}
